class FullTimeEmployee extends Employee {
    // Employee associated with passport
    Optional<Passport> passport = Optional.ofNullable(new Passport()); 
    // passport can be null or non-null

    // Getter and setter for passport
    // Other fields and methods
}

public class EmployeeStarter {
    public static void main(String[] args) {
  // Code to retrieve full-time employees and store them in a list called employeesList
        List<Integer> passportNumbers = new ArrayList<>();  // List to collect passport numbers

        for (FullTimeEmployee employee : employeesList) {
            Optional<FullTimeEmployee> optEmp = Optional.of(employee);  
            // Wrap employee in Optional

            // Use flatMap to handle Optional passport and map to passport number
            passportNumbers.add(
                optEmp.flatMap(FullTimeEmployee::getPassport)  // Get Optional<Passport>
                      .map(Passport::getPassportNo)  // Extract passport number
                      .orElse(0)  // Default to 0 if absent
            );
        }
    }
}

